#!/usr/bin/env bash
# run.sh <run> : Fink art trial, restyles reference/frames.png (2x2 grid of 4 directions, 320x256 cells)
T='D:/Coding/BYMR/art-trials/fink/kit'
R="$T/$1"
date +%T
bash ~/.claude/scripts/agy-delegate.sh --write --yolo --timeout 10m --dir "$R" -- "You are restyling tiny game sprites. Workspace folder: $R. Look at reference/frames.png: a 2x2 grid (cells 320x256 px, flat grey ground) of 4 frames of ONE game monster (the Fink: a round brown/orange saucer-shaped body like a flat spinning top or flying saucer, a thin neck rising from the middle topped by a round brown head with big white eyes and a long thin pointed beak like a kiwi bird, and a ring of small pink/magenta glowing spikes or pegs with dark tips around the rim of the saucer) taken from a low-resolution isometric game sprite sheet, blown up 8x so they are blurry. Each cell is the same monster facing a different direction (top-left: head facing right/east, top-right: facing down/south toward the viewer, bottom-left: facing left/west, bottom-right: facing up/north, showing the back of the head). reference/portrait.png shows the first one larger. TASK: generate ONE new image, saved as out/frames-cel.png, with exactly the same 2x2 grid layout and canvas proportions as reference/frames.png (640x512, or a 2x multiple), every monster at the same position, same size, same pose and same facing as in the matching reference cell - only the drawing style changes. Keep the monster design identical in all 4 cells: same brown saucer body, same neck, same head and beak, same ring of pink spikes. Style: modern 2D cel-shaded game art (Brawl Stars 2D promo art / Hades): bold clean dark outlines, flat colour zones with two-tone shading and one crisp highlight, vivid controlled palette, no painterly blending, no 3D render look, no pixel art. Background must be flat pure #00FF00 green everywhere, no shadows, no grid lines, no text, no labels. IMPORTANT: do NOT write or run any code or scripts, and do NOT warp, morph, cut, copy or composite pixels from any reference image - the new image must be produced by ONE call to your image generation tool, passing reference/frames.png and reference/portrait.png as input images. Then save that generated image to out/frames-cel.png (resizing it is fine). Reply DONE when the file exists." 2>&1 | tail -4
date +%T; ls -la "$R/out"
